def addedInteger(nums1, nums2):
    # Find minimum in both nums1 and nums2
    min_nums1 = nums1[0]
    min_nums2 = nums2[0]
    for n in nums1:
        if n < min_nums1:
            min_nums1 = n
    for n in nums2:
        if n < min_nums2:
            min_nums2 = n
    # The integer x that was added to nums1 is the difference of minima
    return min_nums2 - min_nums1
